function.arguments:
{"command":"python3 << 'EOF'
import csv

# Read the CSV
with open('outputs/t11_city_indicator_matrix.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

print(f'Header: {header}')
print(f'Total rows: {len(rows)}')

# Count missing values per indicator
indicator_names = header[3:]  # Skip city_id, city_name, year
missing_counts = {}
missing_rates = {}

for i, row in enumerate(rows):
    for j, indicator in enumerate(indicator_names):
        val = row[j]
        if val == '':
            missing_counts[indicator] = missing_counts.get(indicator, 0) + 1
            missing_rates[indicator] = missing_rates.get(indicator, 0) + 1 / len(rows)

for ind in sorted(indicator_names):
    print(f'{ind}: missing_count={missing_counts.get(ind, 0)}, missing_rate={missing_rates.get(ind, 0):.6f}')
EOF
"}

