import csv

with open('t11_city_indicator_matrix.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

indicator_names = header[3:]
missing_counts = {}
missing_rates = {}

for i, row in enumerate(rows):
    for j, indicator in enumerate(indicator_names):
        val = row[j]
        if val == '':
            missing_counts[indicator] = missing_counts.get(indicator, 0) + 1
            missing_rates[indicator] = missing_rates.get(indicator, 0) + 1 / len(rows)

kept_indicators = []
for ind in sorted(indicator_names):
    if missing_rates.get(ind, 0) <= 0.30:
        kept_indicators.append(ind)

print(f'Indicators with missing_rate <= 0.30: {kept_indicators}')

report_path = 'outputs/t12_missingness_report.csv'
with open(report_path, 'w', newline='') as f:
    writer = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
    writer.writerow(['indicator', 'missing_count', 'missing_rate', 'kept'])
    for ind in sorted(kept_indicators):
        writer.writerow([ind, missing_counts.get(ind, 0), missing_rates.get(ind, 0), 'yes'])

print(f'Created: {report_path}')

selected_path = 'outputs/t12_selected_matrix.csv'
with open(selected_path, 'w', newline='') as f:
    writer = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
    writer.writerow(['city_id', 'city_name', 'year', 'DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V'])
    for row in rows:
        has_valid = True
        for j, indicator in enumerate(indicator_names):
            val = row[j]
            if val == '':
                has_valid = False
                break
        if has_valid:
            for j in range(len(indicator_names)):
                writer.writerow([row[0], row[1], row[2], row[j]])

print(f'Created: {selected_path}')
"
"}

